mapper.select:
SELECT A.FINPROD_ID FINPROD_ID, A.FINPROD_ABBR FINPROD_ABBR, A.FINPROD_MARKET_ID FINPROD_MARKET_ID, A.VDATE VDATE, A.MDATE MDATE, A.ISSUER ISSUER, A.FINANCIER FINANCIER, A.SPONSOR SPONSOR, A.IS_SUS IS_SUS, A.IS_RIGHT IS_RIGHT, A.CON_FINPROD_ID CON_FINPROD_ID, A.CON_VDATE CON_VDATE, A.CON_PRICE CON_PRICE, A.COUPON_SPECIES COUPON_SPECIES, A.ACTUAL_CREDIT_PROVID ACTUAL_CREDIT_PROVID, A.ASSET_ONE ASSET_ONE, A.ASSET_TWO ASSET_TWO, A.ASSET_THREE ASSET_THREE, A.ASSET_FOUR ASSET_FOUR, A.ASSET_FIVE ASSET_FIVE, A.ISSUER_FIN_LICENCE ISSUER_FIN_LICENCE, A.FINANCIER_FIN_LICENCE FINANCIER_FIN_LICENCE, A.SPONSOR_FIN_LICENCE SPONSOR_FIN_LICENCE, A.ACTUAL_CREDIT_FIN_LICENCE ACTUAL_CREDIT_FIN_LICENCE, A.MODYORN MODYORN, A.ISSUE_PRICE ISSUE_PRICE, B.LAST_TRADE_IN_DATE LAST_TRADE_IN_DATE, B.LAST_TRADE_AVG_PRICE LAST_TRADE_AVG_PRICE, B.LAST_TRADE_NET_PRICE LAST_TRADE_NET_PRICE FROM (SELECT A.FINPROD_ID as FINPROD_ID, A.FINPROD_ABBR as FINPROD_ABBR, A.TRADE_MARKET as TRADE_MARKET, A.FINPROD_MARKET_ID as FINPROD_MARKET_ID, A.VDATE as VDATE, A.MDATE as MDATE, A.ISSUER as ISSUER, A.FINANCIER as FINANCIER, A.SPONSOR as SPONSOR, A.IS_SUS as IS_SUS, A.IS_RIGHT as IS_RIGHT, F.CON_FINPROD_ID as CON_FINPROD_ID, F.CON_SHARE_ID as CON_SHARE_ID, F.CON_VDATE as CON_VDATE, F.CON_PRICE as CON_PRICE, G.ACTUAL_CREDIT_PROVID as ACTUAL_CREDIT_PROVID, H.TYPE_8 as ASSET_ONE, H.TYPE_9 as ASSET_TWO, H.TYPE_10 as ASSET_THREE, H.TYPE_11 as ASSET_FOUR, H.TYPE_12 as ASSET_FIVE, B.IS_FIN_LICENCE as ISSUER_FIN_LICENCE, C.IS_FIN_LICENCE as FINANCIER_FIN_LICENCE, D.IS_FIN_LICENCE as SPONSOR_FIN_LICENCE, E.IS_FIN_LICENCE as ACTUAL_CREDIT_FIN_LICENCE, A.COUPON_SPECIES as COUPON_SPECIES, A.ISSUE_PRICE as ISSUE_PRICE, M.IS_LIMITS as IS_LIMITS, A.ISSUE_AMT AS ISSUE_AMT, CASE WHEN (M.IS_RATE_ADJUST = 'Y' AND A8.CT > 0 ) THEN 'Y' ELSE 'N' END IS_AUTHORITY, CASE WHEN (A1.FINPROD_ID IS NOT NULL OR A2.SEC_DETAIL_TYPE IS NOT NULL OR A4.SEC_TYPE IS NOT NULL) THEN 'Y' ELSE 'N' END MODYORN FROM FIN_PRODUCT A INNER JOIN FIN_PRODUCT_TYPE H ON A.FINPROD_ID = H.FINPROD_ID AND H.BRANCH = 0 LEFT JOIN FIN_PRODUCT_ADD M ON A.FINPROD_ID = M.FINPROD_ID LEFT JOIN FIN_PRODUCT_CONVERTIBLE F ON A.FINPROD_ID = F.FINPROD_ID LEFT JOIN PA_FIN_PRODUCT G ON A.FINPROD_ID = G.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO_ADD B ON A.ISSUER = B.CUSTOMER_ID LEFT JOIN MST_CUSTOMER_INFO_ADD C ON A.FINANCIER = C.CUSTOMER_ID LEFT JOIN MST_CUSTOMER_INFO_ADD D ON A.SPONSOR = D.CUSTOMER_ID LEFT JOIN MST_CUSTOMER_INFO_ADD E ON G.ACTUAL_CREDIT_PROVID = E.CUSTOMER_ID LEFT JOIN ( SELECT DISTINCT FINPROD_ID FROM BOK_VAL_SCHEME_DETAIL_SPECIAL WHERE VALUATION_PRICE = 'MOD' ) A1 ON A.FINPROD_ID = A1.FINPROD_ID LEFT JOIN ( SELECT DISTINCT SEC_DETAIL_TYPE FROM BOK_VAL_SCHEME_DETAIL WHERE VALUATION_PRICE = 'MOD'AND SEC_DETAIL_TYPE IS NOT NULL) A2 ON H.TYPE_1 = A2.SEC_DETAIL_TYPE LEFT JOIN ( SELECT DISTINCT (CASE WHEN SEC_TYPE = '01' THEN 'F01' ELSE 'F06'END ) SEC_TYPE FROM BOK_VAL_SCHEME_DETAIL WHERE VALUATION_PRICE = 'MOD'AND SEC_DETAIL_TYPE IS NULL) A4 ON H.TYPE_8 = A4.SEC_TYPE LEFT JOIN ( SELECT FINPROD_ID,COUNT(1) AS CT FROM FIN_EXERCISE_PLAN PLAN WHERE EXERCISE_TYPE = '01' GROUP BY FINPROD_ID ) A8 ON H.FINPROD_ID = A8.FINPROD_ID WHERE A.FINPROD_TYPE2 IN ('F01','F18') ) A LEFT JOIN (SELECT C.FINPROD_ID, SUM(C.FPRICE_AMT) / SUM(C.SHARE_AMT) AS LAST_TRADE_AVG_PRICE, SUM(C.CPRICE_AMT) / SUM(C.SHARE_AMT) AS LAST_TRADE_NET_PRICE, D.LAST_TRADE_IN_DATE FROM (SELECT NVL(A.TOTLE_TRADE_ID,A.TRADE_ID) AS TOTLE_TRADE_ID, A.FINPROD_ID AS FINPROD_ID, A.FINPROD_TYPE2 AS FINPROD_TYPE2, A.PS AS PS, abs(A.FPRICE_AMT) AS FPRICE_AMT, abs(A.UNIT_FPRICE) AS UNIT_FPRICE, abs(A.CPRICE_AMT) AS CPRICE_AMT, abs(A.UNIT_CPRICE) AS UNIT_CPRICE, abs(A.TRADE_AMT) AS TRADE_AMT, abs(A.PRIN_AMT) AS PRIN_AMT, abs(A.SHARE_AMT) AS SHARE_AMT, A.INV_AIM AS INV_AIM, A.YIELD AS YIELD, A.SETTLE_DATE AS SETTLE_DATE, A.TRADE_DATE AS TRADE_DATE, A.MDATE AS MDATE, A.IS_CLEAN AS IS_CLEAN, P.PORTFOLIO_ID AS PORTFOLIO_ID, C.FINPROD_ID AS PROD_ID, C.FINPROD_ABBR AS PROD_NAME FROM TRD_PRODUCT_DEAL A INNER JOIN PTL_TRADE B ON A.TRADE_ID = B.BUSI_NO INNER JOIN PTL_PORTFOLIO P ON B.PORTFOLIO_ID = P.PORTFOLIO_ID AND P.INVEST_YESORNO = 'Y' LEFT JOIN FIN_PRODUCT C ON (c.FINPROD_MARKET_ID = P.PORTFOLIO_ID or c.FINPROD_MARKET_ID = P.PARENT_PORTFOLIO_ID) AND C.FINPROD_TYPE2 = 'F16' where A.PS IN ('T01', 'T02', 'T03', 'T39', 'T22', 'T23', 'T07', 'T08', 'T09') AND A.IS_CANCEL = 'N' AND A.TRADE_STATUS = '01' AND A.FINPROD_TYPE2 IN ('F01', 'F18' )) C INNER JOIN (SELECT FINPROD_ID, MAX(SETTLE_DATE) AS LAST_TRADE_IN_DATE FROM (SELECT NVL(A.TOTLE_TRADE_ID,A.TRADE_ID) AS TOTLE_TRADE_ID, /*交易编号*/ A.FINPROD_ID AS FINPROD_ID, /*金融产品代码*/ A.FINPROD_TYPE2 AS FINPROD_TYPE2, /*金融产品类型*/ A.PS AS PS, /*交易方向*/ abs(A.FPRICE_AMT) AS FPRICE_AMT, /*全价总额*/ abs(A.UNIT_FPRICE) AS UNIT_FPRICE, /*单位全价*/ abs(A.CPRICE_AMT) AS CPRICE_AMT, /*净价总额*/ abs(A.UNIT_CPRICE) AS UNIT_CPRICE, /*单位净价*/ abs(A.TRADE_AMT) AS TRADE_AMT, /*交易金额*/ abs(A.PRIN_AMT) AS PRIN_AMT, /*计息本金*/ abs(A.SHARE_AMT) AS SHARE_AMT, /*交易份额*/ A.INV_AIM AS INV_AIM, /*投资目的*/ A.YIELD AS YIELD, /*到期收益率 */ A.SETTLE_DATE AS SETTLE_DATE, /*交割日期 */ A.TRADE_DATE AS TRADE_DATE, /*交易日期 */ A.MDATE AS MDATE, /*到期日 */ A.IS_CLEAN AS IS_CLEAN, /*是否结清 */ P.PORTFOLIO_ID AS PORTFOLIO_ID, /*组合代码 */ C.FINPROD_ID AS PROD_ID, /*产品代码*/ C.FINPROD_ABBR AS PROD_NAME /*金融产品简称 */ FROM TRD_PRODUCT_DEAL A INNER JOIN PTL_TRADE B ON A.TRADE_ID = B.BUSI_NO INNER JOIN PTL_PORTFOLIO P ON B.PORTFOLIO_ID = P.PORTFOLIO_ID AND P.INVEST_YESORNO = 'Y' LEFT JOIN FIN_PRODUCT C ON (c.FINPROD_MARKET_ID = P.PORTFOLIO_ID or c.FINPROD_MARKET_ID = P.PARENT_PORTFOLIO_ID) AND C.FINPROD_TYPE2 = 'F16' where A.PS IN ('T01', 'T02', 'T03', 'T39', 'T22', 'T23', 'T07', 'T08', 'T09') AND A.IS_CANCEL = 'N' AND A.TRADE_STATUS = '01' AND A.FINPROD_TYPE2 IN ('F01', 'F18') ) WHERE SETTLE_DATE <= #{searchDate,jdbcType=DATE} AND PS = 'T01' GROUP BY FINPROD_ID) D ON C.FINPROD_ID = D.FINPROD_ID AND C.SETTLE_DATE = D.LAST_TRADE_IN_DATE AND C.PS = 'T01' GROUP BY C.FINPROD_ID, D.LAST_TRADE_IN_DATE) B ON A.FINPROD_ID = B.FINPROD_ID WHERE EXISTS (SELECT 1 FROM (select A.FINPROD_ID, A.CDATE, A.INV_AIM, SUM(A.AMOUNT) AMOUNT from PTL_SEC_POSITION A INNER JOIN PTL_PORTFOLIO C ON A.PORTFOLIO_ID = C.PORTFOLIO_ID AND C.INVEST_YESORNO = 'Y' INNER JOIN FIN_PRODUCT B ON A.FINPROD_ID = B.FINPROD_ID AND B.FINPROD_TYPE2 IN ('F01', 'F18') where A.HODING_TYPE = '03' GROUP BY A.FINPROD_ID, A.CDATE, A.INV_AIM)M WHERE A.FINPROD_ID = M.FINPROD_ID AND M.CDATE = #{searchDate,jdbcType=DATE} AND M.AMOUNT > 0) AND A.MODYORN = 'Y'
AND A.FINPROD_ID IN(
#{item}
)
AND A.ASSET_FIVE IN(
#{item}
)

SELECT A.FINPROD_ID FINPROD_ID, A.FINPROD_ABBR FINPROD_ABBR, A.FINPROD_MARKET_ID FINPROD_MARKET_ID, A.VDATE VDATE, A.MDATE MDATE, A.ISSUER ISSUER, A.FINANCIER FINANCIER, A.SPONSOR SPONSOR, A.IS_SUS IS_SUS, A.IS_RIGHT IS_RIGHT, A.CON_FINPROD_ID CON_FINPROD_ID, A.CON_VDATE CON_VDATE, A.CON_PRICE CON_PRICE, A.COUPON_SPECIES COUPON_SPECIES, A.ACTUAL_CREDIT_PROVID ACTUAL_CREDIT_PROVID, A.ASSET_ONE ASSET_ONE, A.ASSET_TWO ASSET_TWO, A.ASSET_THREE ASSET_THREE, A.ASSET_FOUR ASSET_FOUR, A.ASSET_FIVE ASSET_FIVE, A.ISSUER_FIN_LICENCE ISSUER_FIN_LICENCE, A.FINANCIER_FIN_LICENCE FINANCIER_FIN_LICENCE, A.SPONSOR_FIN_LICENCE SPONSOR_FIN_LICENCE, A.ACTUAL_CREDIT_FIN_LICENCE ACTUAL_CREDIT_FIN_LICENCE, A.ISSUE_AMT ISSUE_AMT, A.COUPON_SPECIES COUPON_SPECIES, A.ISSUE_PRICE ISSUE_PRICE FROM VW_MOD_ASSET_INFO A WHERE EXISTS (SELECT 1 FROM (select A.FINPROD_ID, A.CDATE, A.INV_AIM, SUM(A.AMOUNT) AMOUNT from PTL_SEC_POSITION A INNER JOIN PTL_PORTFOLIO C ON A.PORTFOLIO_ID = C.PORTFOLIO_ID AND C.INVEST_YESORNO = 'Y' INNER JOIN FIN_PRODUCT B ON A.FINPROD_ID = B.FINPROD_ID AND B.FINPROD_TYPE2 IN ('F01', 'F18') where A.HODING_TYPE = '03' GROUP BY A.FINPROD_ID, A.CDATE, A.INV_AIM)M WHERE A.FINPROD_ID = M.FINPROD_ID AND M.INV_AIM = 'AC' AND M.AMOUNT > 0)
AND A.FINPROD_ID IN(
#{item}
)
AND A.ASSET_FIVE IN(
#{item}
)

SELECT A.CON_FINPROD_ID CON_FINPROD_ID, A.FINPROD_MARKET_ID FINPROD_MARKET_ID, A.DEAL_DATE DEAL_DATE, A.CLOSE_PRICE CLOSE_PRICE, A.PB PB, A.PE PE FROM (SELECT F.CON_FINPROD_ID AS CON_FINPROD_ID, C.FINPROD_MARKET_ID AS FINPROD_MARKET_ID, B.DEAL_DATE AS DEAL_DATE, B.CLOSE_PRICE AS CLOSE_PRICE, B.PB AS PB, B.PE AS PE FROM FIN_PRODUCT A INNER JOIN FIN_PRODUCT_TYPE H ON A.FINPROD_ID = H.FINPROD_ID AND H.BRANCH = 0 INNER JOIN FIN_PRODUCT_CONVERTIBLE F ON A.FINPROD_ID = F.FINPROD_ID INNER JOIN FIN_PRODUCT C ON C.FINPROD_ID = F.CON_FINPROD_ID INNER JOIN MST_SHARE_PRICE B ON C.FINPROD_MARKET_ID = B.SHARES_ID WHERE A.FINPROD_TYPE2 IN （ 'F01' ） AND H.TYPE_11 IN ('011', '013') ORDER BY C.FINPROD_MARKET_ID, B.DEAL_DATE desc)A where 1=1
AND A.CON_FINPROD_ID IN(
#{item}
)
AND A.DEAL_DATE >= #{startDate, jdbcType=DATE}
and A.DEAL_DATE <= #{searchDate, jdbcType=DATE}
ORDER BY A.DEAL_DATE

SELECT A.CURVE_DATE CURVE_DATE, A.CURVE_CODE CURVE_CODE, A.KEY_POINT KEY_POINT, A.YIELD YIELD, A.CURVE_TYPE CURVE_TYPE FROM (SELECT A.CURVE_DATE, A.CURVE_CODE, A.KEY_POINT, A.YIELD, A.CURVE_TYPE FROM MST_YIELD_CURVE_INFO A WHERE A.CURVE_CODE IN ('1231', '1232', '1901', '1902', '2221', '2222', '1851', '1852', '2171', '2172', '1251', '1252', '2211', '2212', '2191', '2192', '1441', '1442', '2251', '2252', '1261', '1262', '2201', '2202', '2231', '2232', '2241', '2242', '1911', '1912', '2331', '2332', '2311', '2312', '2161', '2162', '2321', '2322', '1331', '1332', '2301', '2302') order by A.CURVE_CODE, A.CURVE_DATE, A.KEY_POINT)A where 1=1
AND A.CURVE_CODE IN(
#{item}
)
AND A.CURVE_DATE >= #{startDate, jdbcType=DATE}
and A.CURVE_DATE <= #{searchDate, jdbcType=DATE}
ORDER BY A.CURVE_DATE

select * from ( SELECT A.OCODE OCODE, A.OTYPE OTYPE, A.GRADEORGID GRADEORGID, A.GRADEDATE GRADEDATE, A.MSTRATINGRESULT01 GRADERESULT FROM (SELECT A.OCODE AS OCODE, A.OTYPE AS OTYPE, A.INNEROUTER AS INNEROUTER, A.GRADEORGID AS GRADEORGID, A.GRADEDATE AS GRADEDATE, A.NOTICEDATE AS NOTICEDATE, A.SHORTLONGTERM AS SHORTLONGTERM, A.MSTRATINGRESULT01 AS MSTRATINGRESULT01, A.MSTRATINGRESULT02 AS MSTRATINGRESULT02, A.INPUTTYPE AS INPUTTYPE, A.GRADEEXPECTATION AS GRADEEXPECTATION, A.DIRECTIONCHANGE AS DIRECTIONCHANGE, A.ISSUERRATETYPE AS ISSUERRATETYPE FROM ( SELECT MBCR.O_CODE AS OCODE, MBCR.O_TYPE AS OTYPE, '01' AS INNEROUTER, MBCR.GRADE_ORG_ID AS GRADEORGID, MBCR.GRADE_DATE AS GRADEDATE, MBCR.NOTICE_DATE AS NOTICEDATE, MBCR.SHORT_LONG_TERM AS SHORTLONGTERM, MBCR.GRADE_RESULT AS MSTRATINGRESULT01, MRM.GRADE_RESULT_ST AS MSTRATINGRESULT02, MBCR.INPUT_TYPE AS INPUTTYPE, MBCR.GRADE_EXPECTATION AS GRADEEXPECTATION, MBCR.DIRECTION_CHANGE AS DIRECTIONCHANGE, MBCR.ISSUER_RATE_TYPE AS ISSUERRATETYPE FROM MST_BOND_CREDIT_RATING MBCR LEFT JOIN MST_RATING_MATCH MRM ON MBCR.GRADE_RESULT = MRM.GRADE_RESULT_OR UNION ALL SELECT MICR.O_CODE AS OCODE, MICR.O_TYPE AS OTYPE, '02' AS INNEROUTER, MICR.GRADE_ORG_ID AS GRADEORGID, MICR.GRADE_DATE AS GRADEDATE, NULL AS NOTICEDATE, NULL AS SHORTLONGTERM, MICR.GRADE_RESULT AS MSTRATINGRESULT01, MRM1.GRADE_RESULT_ST AS MSTRATINGRESULT02, MICR.INPUT_TYPE AS INPUTTYPE, NULL AS GRADEEXPECTATION, NULL AS DIRECTIONCHANGE, NULL AS ISSUERRATETYPE FROM MST_INNER_CREDIT_RATING MICR LEFT JOIN MST_RATING_MATCH MRM1 ON MICR.GRADE_RESULT = MRM1.GRADE_RESULT_OR) A)A WHERE 1=1
AND A.OCODE = #{ocode,jdbcType=VARCHAR}
AND A.OTYPE = #{otype,jdbcType=VARCHAR}
AND A.GRADEORGID = '98'
AND A.GRADEORGID != '98'
AND A.GRADEDATE <= #{gradedate, jdbcType=DATE}
ORDER BY A.GRADEDATE DESC) where ROWNUM =1

select * from ( SELECT A.OCODE OCODE, A.OTYPE OTYPE, A.GRADEORGID GRADEORGID, A.GRADEDATE GRADEDATE, A.MSTRATINGRESULT01 GRADERESULT FROM (SELECT A.OCODE AS OCODE, A.OTYPE AS OTYPE, A.INNEROUTER AS INNEROUTER, A.GRADEORGID AS GRADEORGID, A.GRADEDATE AS GRADEDATE, A.NOTICEDATE AS NOTICEDATE, A.SHORTLONGTERM AS SHORTLONGTERM, A.MSTRATINGRESULT01 AS MSTRATINGRESULT01, A.MSTRATINGRESULT02 AS MSTRATINGRESULT02, A.INPUTTYPE AS INPUTTYPE, A.GRADEEXPECTATION AS GRADEEXPECTATION, A.DIRECTIONCHANGE AS DIRECTIONCHANGE, A.ISSUERRATETYPE AS ISSUERRATETYPE FROM ( SELECT MBCR.O_CODE AS OCODE, MBCR.O_TYPE AS OTYPE, '01' AS INNEROUTER, MBCR.GRADE_ORG_ID AS GRADEORGID, MBCR.GRADE_DATE AS GRADEDATE, MBCR.NOTICE_DATE AS NOTICEDATE, MBCR.SHORT_LONG_TERM AS SHORTLONGTERM, MBCR.GRADE_RESULT AS MSTRATINGRESULT01, MRM.GRADE_RESULT_ST AS MSTRATINGRESULT02, MBCR.INPUT_TYPE AS INPUTTYPE, MBCR.GRADE_EXPECTATION AS GRADEEXPECTATION, MBCR.DIRECTION_CHANGE AS DIRECTIONCHANGE, MBCR.ISSUER_RATE_TYPE AS ISSUERRATETYPE FROM MST_BOND_CREDIT_RATING MBCR LEFT JOIN MST_RATING_MATCH MRM ON MBCR.GRADE_RESULT = MRM.GRADE_RESULT_OR UNION ALL SELECT MICR.O_CODE AS OCODE, MICR.O_TYPE AS OTYPE, '02' AS INNEROUTER, MICR.GRADE_ORG_ID AS GRADEORGID, MICR.GRADE_DATE AS GRADEDATE, NULL AS NOTICEDATE, NULL AS SHORTLONGTERM, MICR.GRADE_RESULT AS MSTRATINGRESULT01, MRM1.GRADE_RESULT_ST AS MSTRATINGRESULT02, MICR.INPUT_TYPE AS INPUTTYPE, NULL AS GRADEEXPECTATION, NULL AS DIRECTIONCHANGE, NULL AS ISSUERRATETYPE FROM MST_INNER_CREDIT_RATING MICR LEFT JOIN MST_RATING_MATCH MRM1 ON MICR.GRADE_RESULT = MRM1.GRADE_RESULT_OR) A)A WHERE 1=1
AND A.OCODE IN(
#{item}
)
AND A.OTYPE = '01' AND A.GRADEORGID = #{gradeorgId,jdbcType=VARCHAR} AND A.GRADEDATE <= #{searchDate, jdbcType=DATE} ORDER BY A.GRADEDATE DESC) where ROWNUM =1
